import java.io.*; import java.net.*;
public class SchoolNetworkingDemo { public static void main(String[] args)throws Exception{try(ServerSocket server=new ServerSocket(0)){int port=server.getLocalPort();Thread worker=new Thread(()->{try(Socket client=server.accept();BufferedReader in=new BufferedReader(new InputStreamReader(client.getInputStream()));PrintWriter out=new PrintWriter(client.getOutputStream(),true)){out.println("School server received: "+in.readLine());}catch(IOException e){throw new RuntimeException(e);}});worker.start();try(Socket client=new Socket("localhost",port);PrintWriter out=new PrintWriter(client.getOutputStream(),true);BufferedReader in=new BufferedReader(new InputStreamReader(client.getInputStream()))){out.println("HELLO SCHOOL");System.out.println(in.readLine());}worker.join();}} }
